def language_code(g):
 try:
  x=str(g['language'] or 'en')
 except Exception:
  x='en'
 return x if x in SUPPORTED_LANGUAGES else 'en'

def other_label(g):
 return OTHER_LABELS.get(language_code(g), OTHER_LABELS['en'])

def localized_general(g):
 lang=language_code(g)
 return GENERAL_BY_LANGUAGE.get(lang, [])

def callback_text(g,sub,old):
 lang=language_code(g);name=sub['name']
 packs={
  'en':(f'⚡ PLOT TWIST: Earlier {name} chose “{old}”. Tomorrow that choice becomes real with no cancel button. What does {name} do first?',['Goes all in','Tries to upgrade the plan','Panics but continues','Pulls someone else into it']),
  'es':(f'⚡ PLOT TWIST: Antes {name} eligió “{old}”. Mañana esa elección se vuelve real y no se puede cancelar. ¿Qué hace primero?',['Va con todo','Intenta mejorar el plan','Se asusta pero sigue','Arrastra a alguien más']),
  'pt-BR':(f'⚡ PLOT TWIST: Antes {name} escolheu “{old}”. Amanhã isso vira realidade e não dá para cancelar. O que faz primeiro?',['Vai com tudo','Tenta melhorar o plano','Entra em pânico mas continua','Puxa alguém junto']),
  'fr':(f'⚡ PLOT TWIST : plus tôt, {name} a choisi « {old} ». Demain, ce choix devient réel et impossible à annuler. Première réaction ?',['Y va à fond','Essaie d’améliorer le plan','Panique mais continue','Embarque quelqu’un avec lui/elle']),
  'ja':(f'⚡ PLOT TWIST：さっき{name}は「{old}」を選びました。明日それが本当に起きて、キャンセル不可。最初にどうする？',['全力で乗る','もっと良いプランにする','焦るけど続ける','誰かを巻き込む']),
 }
 return packs.get(lang)

def match_prompt(g,a,b):
 lang=language_code(g)
 packs={
  'en':f'⚡ {a} and {b}: secretly write one thing you would choose to do together on a completely free weekend. Same answer = +1 each.',
  'es':f'⚡ {a} y {b}: escriban en secreto una cosa que harían juntos en un fin de semana totalmente libre. Misma respuesta = +1 cada uno.',
  'pt-BR':f'⚡ {a} e {b}: cada um escreve em segredo uma coisa que fariam juntos num fim de semana totalmente livre. Mesma resposta = +1 para cada.',
  'fr':f'⚡ {a} et {b} : écrivez chacun en secret une chose que vous feriez ensemble pendant un week-end totalement libre. Même réponse = +1 chacun.',
  'ja':f'⚡ {a} と {b}：完全に自由な週末に2人でやりたいことを、1つずつ秘密で書いてください。同じ答えなら2人とも+1。',
 }
 return packs.get(lang,'')


def last_resort_question(g,name):
 lang=language_code(g)
 packs={
  'en':(f'What would surprise people who think they know {name} well?',['A spontaneous choice','The safe choice','Something nobody expects','It depends']),
  'es':(f'¿Qué sorprendería a quienes creen conocer muy bien a {name}?',['Una elección espontánea','La opción segura','Algo que nadie espera','Depende de la situación']),
  'pt-BR':(f'O que surpreenderia quem acha que conhece {name} muito bem?',['Uma escolha espontânea','A opção segura','Algo que ninguém espera','Depende da situação']),
  'fr':(f'Qu’est-ce qui surprendrait ceux qui pensent très bien connaître {name} ?',['Un choix spontané','Le choix prudent','Quelque chose d’inattendu','Ça dépend']),
  'ja':(f'{name}のことをよく知っていると思う人が一番驚きそうなのは？',['思い切った選択','安全な選択','誰も予想しないこと','状況次第']),
  'he':(f'מה הכי יפתיע את מי שחושב שהוא מכיר את {name} טוב?',['בחירה ספונטנית','בחירה בטוחה','משהו שאף אחד לא מצפה לו','תלוי במצב']),
 }
 return packs.get(lang,packs['en'])
